css:
.mas-print { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 10px; }
.mas-print .mas-title { text-align: center; font-size: 15px; font-weight: 700; margin-bottom: 2px; text-transform: uppercase; }
.mas-print .mas-meta { display: flex; justify-content: space-between; font-size: 10px; margin-bottom: 8px; }
.mas-print .mas-meta > div > div { margin-bottom: 2px; }
.mas-print .mas-meta .right { text-align: right; }
.mas-print table { width: auto; table-layout: auto; border-collapse: collapse; }
.mas-print th, .mas-print td { border: 1px solid #000; padding: 2px 4px; text-align: center; white-space: nowrap; width: 1px; }
.mas-print th { background: #eee; font-weight: 700; }
.mas-print td.col-text, .mas-print th.col-text { text-align: left; }
.mas-print .col-day { font-size: 8px; padding: 2px 1px; }
.mas-print .col-sign { width: 70px; }
.mas-print tr.ta-summary-row td { font-weight: 700; background: #fafafa; }
@page { size: A4 landscape; margin: 8mm; }
@media print {
    thead { display: table-header-group; }
    tr { page-break-inside: avoid; }
}

html:
{%
    var day_re = /^\d{2}-\d{2}-\d{4}$/;
    var cols = (columns || []).filter(function (c) { return c.fieldname && c.fieldname !== "_check" && c.fieldname !== "shift"; });
    var rows = data || [];
    var text_fields = { employee: 1, employee_name: 1 };

    var period = "";
    if (filters.filter_based_on === "Date Range" && filters.start_date && filters.end_date) {
        period = frappe.datetime.str_to_user(filters.start_date) + " - " + frappe.datetime.str_to_user(filters.end_date);
    } else if (filters.month && filters.year) {
        var MONTH_NAMES = ["", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
        period = (MONTH_NAMES[cint(filters.month)] || filters.month) + " " + filters.year;
    }

    var company = filters.company || "";
    var unit_division = filters.unit_division || "";
    var department = (filters.department && filters.department !== "All Departments") ? filters.department : "";
%}
<div class="mas-print">
    <div class="mas-title">{%= __(report.report_name || "Monthly Attendance Sheet") %}</div>
    <div class="mas-meta">
        <div class="left">
            {% if (company) { %}<div><b>{%= __("Company") %}:</b> {%= company %}</div>{% } %}
            {% if (unit_division) { %}<div><b>{%= __("Unit/Division") %}:</b> {%= unit_division %}</div>{% } %}
            {% if (department) { %}<div><b>{%= __("Department") %}:</b> {%= department %}</div>{% } %}
        </div>
        <div class="right">
            {% if (period) { %}<div><b>{%= __("Period") %}:</b> {%= period %}</div>{% } %}
            <div><b>{%= __("Printed on") %}:</b> {%= frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string()) %}</div>
        </div>
    </div>

    <table>
        <thead>
            <tr>
                {% for (var i = 0; i < cols.length; i++) { var col = cols[i]; %}
                <th class="{%= day_re.test(col.fieldname) ? "col-day" : (text_fields[col.fieldname] ? "col-text" : "") %}">
                    {%= __(col.label || col.name || col.fieldname) %}
                </th>
                {% } %}
                <th class="col-sign">{%= __("Sign") %}</th>
            </tr>
        </thead>
        <tbody>
            {% for (var r = 0; r < rows.length; r++) { var row = rows[r]; %}
            <tr class="{%= row._is_summary ? "ta-summary-row" : "" %}">
                {% for (var i = 0; i < cols.length; i++) { var col = cols[i]; var v = row[col.fieldname]; %}
                <td class="{%= day_re.test(col.fieldname) ? "col-day" : (text_fields[col.fieldname] ? "col-text" : "") %}">
                    {%= (v === undefined || v === null) ? "" : v %}
                </td>
                {% } %}
                <td class="col-sign">&nbsp;</td>
            </tr>
            {% } %}
        </tbody>
    </table>
</div>
